### Recommendation 2: Implement Proper Secret Loading Pattern

Here's how to implement secure secret loading in `app.js`:

```javascript
// app.js - Secure secret loading pattern

const dotenv = require('dotenv');
const path = require('path');

// Load environment-specific .env file
const env = process.env.NODE_ENV || 'development';
const envFile = `.env.${env}`;

// Only load .env files in non-production environments
if (env !== 'production') {
  const envPath = path.resolve(process.cwd(), envFile);
  dotenv.config({ path: envPath });
}

// Critical: Validate required secrets on startup
const requiredSecrets = {
  // Add secrets as your app grows
  // JWT_SECRET: process.env.JWT_SECRET,
  // DATABASE_URL: process.env.DATABASE_URL,
  // SESSION_SECRET: process.env.SESSION_SECRET,
};

const missingSecrets = Object.entries(requiredSecrets)
  .filter(([_, value]) => !value)
  .map(([key]) => key);

if (missingSecrets.length > 0) {
  console.error('FATAL: Missing required environment variables:');
  missingSecrets.forEach(secret => console.error(`  - ${secret}`));
  process.exit(1);
}

// In production, log a warning if .env files are being loaded
if (env === 'production' && process.env.DOTENV_LOADED) {
  console.warn('WARNING: .env file loaded in production. Use proper secret management.');
}
```

### Recommendation 3: Use Secure Secret Manager Integration

For production, implement a secrets manager pattern:

```javascript
// secrets.js - Secret management abstraction
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
  }

  async getSecret(secretName) {
    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();

      if ('SecretString' in data) {
        return JSON.parse(data.SecretString);
      }

      // Handle binary secrets
      return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw error;
    }
  }
}

// Usage in app.js
async function loadSecrets() {
  if (process.env.NODE_ENV === 'production') {
    const secretsManager = new SecretsManager();
    const secrets = await secretsManager.getSecret('myapp/production');

    // Map secrets to process.env
    process.env.DATABASE_URL = secrets.database_url;
    process.env.JWT_SECRET = secrets.jwt_secret;
  } else {
    // Load from .env file for development
    dotenv.config();
  }
}
```

