#### 4. **Secrets Manager Integration (Production Recommendation)**

```javascript
// config/secretManager.js
const AWS = require('aws-sdk');
const awsConfig = require('../config');

// AWS Secrets Manager
const secretsManager = new AWS.SecretsManager({
  region: awsConfig.aws.region,
  accessKeyId: awsConfig.aws.accessKeyId,
  secretAccessKey: awsConfig.aws.secretAccessKey,
});

const getSecret = async (secretName) => {
  try {
    const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    }

    return Buffer.from(data.SecretBinary, 'base64').toString();
  } catch (error) {
    console.error(`Error retrieving secret ${secretName}:`, error);
    throw error;
  }
};

// Load all secrets at startup
const loadSecrets = async () => {
  if (process.env.NODE_ENV === 'production') {
    const dbSecret = await getSecret('production/myapp/database');
    const jwtSecret = await getSecret('production/myapp/jwt');

    return {
      database: {
        url: dbSecret.url,
        username: dbSecret.username,
        password: dbSecret.password,
      },
      jwt: {
        secret: jwtSecret.secret,
      },
    };
  }

  // Local development - use .env
  return {
    database: {
      url: process.env.DATABASE_URL,
    },
    jwt: {
      secret: process.env.JWT_SECRET,
    },
  };
};

module.exports = { getSecret, loadSecrets };
```

