};

// Graceful secret rotation without downtime
const rotateJwtSecret = async () => {
  const currentSecret = secrets.jwt.secret;
  const newSecret = generateSecret(64);

  // Store both for transition period
  secrets.jwt.oldSecret = currentSecret;
  secrets.jwt.secret = newSecret;

  // Update in secrets manager
  await rotateSecret('production/myapp/jwt', newSecret);

  // Schedule removal of old secret (e.g., 24 hours)
  setTimeout(() => {
    delete secrets.jwt.oldSecret;
