```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secretData = response.SecretString 
        ? JSON.parse(response.SecretString)
        : { binary: response.SecretBinary };

      // Cache the result
      this.cache.set(secretName, {
        value: secretData,
        timestamp: Date.now()
      });

      return secretData;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  async loadAllSecrets() {
    try {
      const dbSecrets = await this.getSecret('prod/database');
      const apiSecrets = await this.getSecret('prod/api-keys');

      // Set environment variables programmatically
      process.env.DATABASE_URL = dbSecrets.connection_string;
      process.env.JWT_SECRET = apiSecrets.jwt_secret;
      process.env.AWS_ACCESS_KEY_ID = apiSecrets.aws_access_key;
      process.env.AWS_SECRET_ACCESS_KEY = apiSecrets.aws_secret_key;

      return true;
    } catch (error) {
      throw error;
    }
  }
}

module.exports = new SecretsManager();
```

