/**
 * AWS Secrets Manager Integration
 * Securely loads secrets from AWS Secrets Manager with local fallback for development
 */

const AWS = require('aws-sdk');
const { fromIni } = require('@aws-sdk/credential-providers');

// Secret names in AWS Secrets Manager
const SECRET_NAMES = {
  DATABASE: 'prod/app/database',
  AWS_CREDS: 'prod/app/aws',
  ANTHROPIC: 'prod/app/anthropic',
  STRIPE: 'prod/app/stripe',
  LOGFIRE: 'prod/app/logfire'
};

/**
 * Fetch secret from AWS Secrets Manager
 */
async function getSecretFromAWS(secretName) {
  const region = process.env.AWS_REGION || 'us-east-1';

  const client = new AWS.SecretsManager({
    region,
    credentials: fromIni({ profile: process.env.AWS_PROFILE || 'default' })
  });

  try {
    const data = await client.getSecretValue({ SecretId: secretName }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    }

    // Binary secret
    const buff = Buffer.from(data.SecretBinary, 'base64');
    return JSON.parse(buff.toString('ascii'));

  } catch (error) {
    if (error.code === 'ResourceNotFoundException') {
      throw new Error(`Secret ${secretName} not found in AWS Secrets Manager`);
    }
    throw error;
  }
}

/**
 * Load secrets with fallback: AWS Secrets Manager -> Local .env file
 * Uses cache to avoid repeated AWS calls
 */
class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheExpiry = 5 * 60 * 1000; // 5 minutes
  }

  async loadSecret(secretName, forceRefresh = false) {
    const cacheKey = secretName;
    const cached = this.cache.get(cacheKey);

    if (!forceRefresh && cached && Date.now() - cached.timestamp < this.cacheExpiry) {
      return cached.data;
    }

    // Try AWS Secrets Manager first (in non-development environments)
    if (process.env.NODE_ENV !== 'development' && process.env.NODE_ENV !== 'test') {
      try {
        const secret = await getSecretFromAWS(secretName);
        this.cache.set(cacheKey, { data: secret, timestamp: Date.now() });
        // Mask secrets in logs
        console.log(`Loaded secret from AWS: ${this.maskSecretName(secretName)}`);
        return secret;
      } catch (error) {
        console.warn(`Failed to load from AWS Secrets Manager (${error.message}), falling back to environment`);
      }
    }

    // Fallback to environment variables
    const envSecret = this.loadFromEnv();
    if (envSecret) {
      this.cache.set(cacheKey, { data: envSecret, timestamp: Date.now() });
      console.log(`Loaded secrets from environment variables`);
      return envSecret;
    }

    throw new Error(`Unable to load secrets. AWS Secrets Manager unavailable and no env variables set.`);
  }

  loadFromEnv() {
    return {
      database: {
        url: process.env.DATABASE_URL
      },
      aws: {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
        region: process.env.AWS_REGION || 'us-east-1'
      },
      anthropic: {
        apiKey: process.env.ANTHROPIC_API_KEY
      },
      stripe: {
        secretKey: process.env.STRIPE_SECRET_KEY
      },
      logfire: {
        token: process.env.LOGFIRE_TOKEN
      }
    };
  }

  /**
   * Get all secrets
   */
  async getAllSecrets() {
    return this.loadFromEnv(); // For now, load from env
  }

  /**
   * Get individual secret value
   */
  async getSecret(key) {
    const secrets = await this.getAllSecrets();
    const keys = key.split('.');
    let value = secrets;

    for (const k of keys) {
      if (value && typeof value === 'object' && k in value) {
        value = value[k];
      } else {
        return undefined;
      }
    }

    return value;
  }

  /**
   * Mask secret name for safe logging
   */
  maskSecretName(name) {
    if (!name) return 'unknown';
    const parts = name.split('/');
    const lastPart = parts[parts.length - 1];
    return lastPart.substring(0, 3) + '***';
  }

  /**
   * Clear the cache
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Rotate secret (trigger AWS rotation)
   */
  async rotateSecret(secretName) {
    const region = process.env.AWS_REGION || 'us-east-1';
    const client = new AWS.SecretsManager({ region });

    await client.rotateSecret({
      SecretId: secretName,
      RotationLambdaARN: process.env.ROTATION_LAMBDA_ARN
    }).promise();

    this.clearCache();
    console.log(`Secret rotation initiated: ${this.maskSecretName(secretName)}`);
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = {
  secretsManager,
  getSecret: (key) => secretsManager.getSecret(key),
  getAllSecrets: () => secretsManager.getAllSecrets()
};

