    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Verify token here
  next();
};

// Middleware to prevent common injection patterns
const detectInjection = (req, res, next) => {
  const checkString = (str) => {
    if (typeof str !== 'string') return false;
    const patterns = [
      /\$\w+/,           // NoSQL operators
      /<script/i,        // XSS
      /javascript:/i,    // XSS
      /on\w+\s*=/i,      // XSS event handlers
      /union.*select/i,  // SQL injection
      /--/,              // SQL comment
      /\/\*/,            // SQL comment
      /\*//,             // SQL comment (unclosed)
    ];
    return patterns.some(p => p.test(str));
  };

  const checkObject = (obj) => {
    for (const key in obj) {
      if (checkString(obj[key]) || checkString(key)) {
        return true;
      }
      if (typeof obj[key] === 'object' && checkObject(obj[key])) {
        return true;
      }
    }
    return false;
  };

  if (checkObject(req.query) || checkObject(req.body) || checkObject(req.params)) {
    return res.status(400).json({ error: 'Invalid input detected' });
  }

  next();
};

app.use(detectInjection);

// Health endpoint (public)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint (protected)
app.get('/users', 
  authenticateToken,
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  validateRequest,
  (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// Error handling
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Internal server error' });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Only listen if not in test mode
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;
