/**
 * Secure Secrets Management Module
 * 
 * This module provides a unified interface for accessing secrets from multiple sources:
 * 1. Environment variables (for local development)
 * 2. AWS Secrets Manager (for production)
 * 3. HashiCorp Vault (optional, for enterprise)
 * 
 * Priority: Secrets Manager > Environment Variables > Default Values
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const dotenv = require('dotenv');

// Load environment variables from .env file only in non-production
if (process.env.NODE_ENV !== 'production') {
  dotenv.config();
}

/**
 * Validates that required secrets are present
 * @throws {Error} If required secret is missing
 */
function validateRequiredSecret(name, value) {
  if (!value || value === '' || value.includes('your_') || value.includes('CANARY')) {
    throw new Error(
      `Required secret '${name}' is missing or using placeholder value.\n` +
      `Set it via environment variable or configure Secrets Manager.`
    );
  }
}

/**
 * Secure Secrets Manager Class
 */
class SecretsManager {
  constructor() {
    this.secretsManager = null;
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes

    // Initialize AWS Secrets Manager if credentials are available
    if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY) {
      this.secretsManager = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1',
      });
    }

    // Validate critical secrets on initialization
    this.validateCriticalSecrets();
  }

  /**
   * Validates critical secrets are present at startup
   */
  validateCriticalSecrets() {
    const criticalSecrets = ['DATABASE_URL', 'JWT_SECRET'];

    for (const secretName of criticalSecrets) {
      try {
        const value = this.getSecret(secretName);
        validateRequiredSecret(secretName, value);
      } catch (error) {
        if (process.env.NODE_ENV === 'production') {
          console.error(`❌ Critical secret validation failed: ${secretName}`);
          throw error;
        } else {
          console.warn(`⚠️  Warning: ${secretName} not properly configured`);
        }
      }
    }
  }

  /**
   * Retrieve a secret from AWS Secrets Manager
   * @param {string} secretName - Name of the secret in AWS Secrets Manager
   * @returns {Promise<string|null>}
   */
  async getSecretFromAWS(secretName) {
    if (!this.secretsManager) {
      return null;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
      });

      const response = await this.secretsManager.send(command);

      if (response.SecretString) {
        return JSON.parse(response.SecretString);
      } else if (response.SecretBinary) {
        return Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      }

      return null;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        return null;
      }
      console.error(`Error fetching secret '${secretName}' from AWS:`, error.message);
      return null;
    }
  }

  /**
   * Get a secret with automatic caching
   * Checks in order: Cache -> AWS Secrets Manager -> Environment Variables -> Default
   * 
   * @param {string} key - Secret key name
   * @param {any} defaultValue - Default value if secret not found
   * @returns {any} Secret value
   */
  async getSecret(key, defaultValue = null) {
    // Check cache first
    if (this.cache.has(key)) {
      const cached = this.cache.get(key);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
      this.cache.delete(key);
    }

    // Try AWS Secrets Manager (mapped: DB_URL -> production/db/url)
    const awsSecretName = this.mapToAWSSecretName(key);
    const awsValue = await this.getSecretFromAWS(awsSecretName);

    if (awsValue) {
      const secretValue = typeof awsValue === 'object' ? awsValue[key] : awsValue;
      this.cache.set(key, { value: secretValue, timestamp: Date.now() });
      return secretValue;
    }

    // Fall back to environment variables
    const envValue = process.env[key];
    if (envValue) {
      this.cache.set(key, { value: envValue, timestamp: Date.now() });
      return envValue;
    }

    // Return default value
    if (defaultValue !== null) {
      return defaultValue;
    }

    throw new Error(`Secret '${key}' not found in any secrets source`);
  }

  /**
   * synchronous version for secrets that must be available immediately
   * Only checks environment variables (useful for startup)
   */
  getSecretSync(key, defaultValue = null) {
    const value = process.env[key];
    if (value) {
      return value;
    }
    if (defaultValue !== null) {
      return defaultValue;
    }
    throw new Error(`Secret '${key}' not found in environment variables`);
  }

  /**
   * Map application secret names to AWS Secrets Manager paths
   */
  mapToAWSSecretName(key) {
    const mappings = {
      'DATABASE_URL': `${process.env.NODE_ENV || 'production'}/app/database`,
      'JWT_SECRET': `${process.env.NODE_ENV || 'production'}/app/jwt`,
      'ANTHROPIC_API_KEY': `${process.env.NODE_ENV || 'production'}/app/anthropic`,
      'STRIPE_SECRET_KEY': `${process.env.NODE_ENV || 'production'}/app/stripe`,
      'AWS_ACCESS_KEY_ID': `${process.env.NODE_ENV || 'production'}/aws/credentials`,
      'AWS_SECRET_ACCESS_KEY': `${process.env.NODE_ENV || 'production'}/aws/credentials`,
    };

    return mappings[key] || `${process.env.NODE_ENV || 'production'}/app/${key.toLowerCase()}`;
  }

  /**
   * Clear the secrets cache
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Get all database configuration
   */
  async getDatabaseConfig() {
    const url = await this.getSecret('DATABASE_URL');

    // Parse connection URL (basic parsing - consider using 'pg-connection-string')
    const urlObj = new URL(url);

    return {
      host: urlObj.hostname,
      port: parseInt(urlObj.port) || 5432,
      database: urlObj.pathname.substring(1),
      username: urlObj.username,
      password: urlObj.password,
      ssl: process.env.NODE_ENV === 'production',
      connectionLimit: parseInt(process.env.DB_POOL_SIZE || '10'),
    };
  }
}

// Export singleton instance
const secretsManager = new SecretsManager();

// Export individual secrets getter for convenience
const getSecret = (key, defaultValue) => secretsManager.getSecret(key, defaultValue);
const getSecretSync = (key, defaultValue) => secretsManager.getSecretSync(key, defaultValue);

module.exports = {
  secretsManager,
  getSecret,
  getSecretSync,
};

/**
 * Secure Bootstrap File
 * 
 * This is the entry point that properly initializes the application
 * with secure secrets management.
 */

const app = require('./app');
const { getSecret } = require('./secrets-manager');

// Validate required secrets before starting server
async function startServer() {
  try {
    console.log('🔐 Validating secrets configuration...');

    // Validate critical secrets
    const requiredSecrets = [
      'JWT_SECRET',
      'DATABASE_URL',
    ];

    for (const secret of requiredSecrets) {
      try {
        const value = await getSecret(secret);

        // Check for placeholder values
        if (value.includes('your_') || value.includes('CANARY')) {
          throw new Error(`Secret '${secret}' contains placeholder value`);
        }

        // Don't log actual values - just confirm they're present
        console.log(`✓ ${secret}: Configured`);
      } catch (error) {
        console.error(`✗ ${secret}: Missing or invalid`);

        if (process.env.NODE_ENV === 'production') {
          throw new Error(`Cannot start without required secret: ${secret}`);
        } else {
          console.warn(`⚠️  Running in development mode without ${secret}`);
        }
      }
    }

    // Get port from secrets or use default
    const PORT = await getSecret('PORT', '3000');
    const NODE_ENV = await getSecret('NODE_ENV', 'development');

    console.log(`\n🚀 Starting server in ${NODE_ENV} mode...\n`);

    // Start server
    const server = app.listen(PORT, () => {
      console.log(`✅ Server is running on port ${PORT}`);
      console.log(`🌍 Environment: ${NODE_ENV}`);
      console.log(`📍 PID: ${process.pid}`);
      console.log('');

      // Security warning for development
      if (NODE_ENV !== 'production') {
        console.warn('⚠️  WARNING: Running in development mode!');
        console.warn('⚠️  - Do not use in production');
        console.warn('⚠️  - Secrets may be loaded from .env file');
        console.warn('');
      }
    });

    // Graceful shutdown handling
    const gracefulShutdown = (signal) => {
      console.log(`\n${signal} received. Starting graceful shutdown...`);

      server.close(() => {
        console.log('✅ HTTP server closed');
        process.exit(0);
      });

      // Force shutdown after 10 seconds
      setTimeout(() => {
        console.error('❌ Forced shutdown after timeout');
        process.exit(1);
      }, 10 * 1000);
    };

    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));

    // Handle uncaught exceptions
    process.on('uncaughtException', (error) => {
      console.error('❌ Uncaught Exception:', error);
      gracefulShutdown('uncaughtException');
    });

    process.on('unhandledRejection', (reason, promise) => {
      console.error('❌ Unhandled Rejection at:', promise, 'reason:', reason);
    });

  } catch (error) {
    console.error('❌ Failed to start server:', error.message);
    process.exit(1);
  }
}

// Start server
startServer();

