const Joi = require('joi');

// Joi schemas for validation
const configSchema = Joi.object({
  // Non-sensitive configuration
  NODE_ENV: Joi.string()
    .valid('development', 'test', 'production')
    .default('development'),
  PORT: Joi.number().port().default(3000),
