    is: 'production',
    then: Joi.forbidden(),
    otherwise: Joi.string().required().messages({
      'any.required': 'DATABASE_URL is required in non-production environments'
    })
  }),
  JWT_SECRET: Joi.string().min(32).when('NODE_ENV', {
    is: 'production',
    then: Joi.forbidden(),
    otherwise: Joi.string().min(32).required()
  })
}).unknown(true); // Allow unknown env vars in dev only

function validateEnvVars() {
  const { error, value } = configSchema.validate(process.env, {
    abortEarly: false,
    stripUnknown: process.env.NODE_ENV === 'production'
  });

  if (error) {
    const messages = error.details.map(d => d.message);
    console.error('Environment validation failed:');
    messages.forEach(m => console.error(`  - ${m}`));

    if (process.env.NODE_ENV === 'production') {
      throw new Error('Invalid environment configuration');
    }
  }

  return value;
}

module.exports = { validateEnvVars };
