#### Option A: AWS Secrets Manager (Production-Grade)
```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

// Initialize Secrets Manager
const secretsClient = new SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache secrets to avoid frequent API calls
let secretsCache = null;
let cacheExpiry = null;
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function getSecrets() {
  // Return cached secrets if still valid
  if (secretsCache && cacheExpiry && Date.now() < cacheExpiry) {
    return secretsCache;
  }

  try {
    const response = await secretsClient.getSecretValue({
      SecretId: process.env.SECRETS_ARN || 'myapp/production'
    });

    if ('SecretString' in response) {
      secretsCache = JSON.parse(response.SecretString);
    } else {
      secretsCache = JSON.parse(Buffer.from(response.SecretBinary, 'base64').toString());
    }

    cacheExpiry = Date.now() + CACHE_TTL;
    return secretsCache;

  } catch (error) {
    console.error('Failed to retrieve secrets:', error);
    throw new Error('Unable to load secrets');
  }
}

module.exports = { getSecrets };
```

