### 4. **Implement Secret Rotation**

```javascript
// config/secret-rotator.js
const { getSecrets } = require('./secrets');
let currentSecrets = null;
let lastRotation = null;
const ROTATION_INTERVAL = 24 * 60 * 60 * 1000; // 24 hours

async function getRotatedSecrets() {
  const now = Date.now();

  if (!currentSecrets || !lastRotation || (now - lastRotation > ROTATION_INTERVAL)) {
    console.log('Rotating secrets...');
    currentSecrets = await getSecrets();
    lastRotation = now;
  }

  return currentSecrets;
}

// Graceful rotation - support old secrets for a period
async function getSecretsWithGrace(key, gracePeriodMs = 5 * 60 * 1000) {
  const secrets = await getRotatedSecrets();
  const newSecret = secrets[key];
  const oldSecret = secrets[`${key}_previous`];

  // During grace period, try new first, fall back to old
  if (Date.now() - lastRotation < gracePeriodMs && oldSecret) {
    return { new: newSecret, old: oldSecret };
  }

  return { new: newSecret, old: null };
}

module.exports = { getRotatedSecrets, getSecretsWithGrace };
```

