```javascript
// Secure environment file loader for local development
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

function decryptEnvFile(encryptedPath, key) {
  const encrypted = fs.readFileSync(encryptedPath, 'utf8');

  // Extract IV and encrypted data
  const parts = encrypted.split(':');
  const iv = Buffer.from(parts[0], 'hex');
  const encryptedData = parts[1];

  const decipher = crypto.createDecipheriv('aes-256-cbc', 
    Buffer.from(key, 'hex'), 
    iv
  );

  let decrypted = decipher.update(encryptedData, 'hex', 'utf8');
  decrypted += decipher.final('utf8');

  return decrypted;
}

// Only use this in development with encrypted env files
if (process.env.NODE_ENV === 'development') {
  const DECRYPTION_KEY = process.env.ENV_DECRYPTION_KEY; // Set from system keychain

  if (DECRYPTION_KEY) {
    const envContent = decryptEnvFile('.env.encrypted', DECRYPTION_KEY);
    const lines = envContent.split('\n');

    lines.forEach(line => {
      const [key, value] = line.split('=');
      if (key && value) {
        process.env[key.trim()] = value.trim();
      }
    });
  }
}
