### 6. **Audit Current Secrets**

```javascript
// scripts/audit-secrets.js
const fs = require('fs');
const path = require('path');

const SECRET_PATTERNS = [
  { name: 'AWS Key', pattern: /AKIA[0-9A-Z]{16}/ },
  { name: 'JWT Secret', pattern: /(jwt|secret).*=.+/i },
  { name: 'Database URL', pattern: /postgres(?:ql)?:\/\/[^@]+@[^\/]+/ },
  { name: 'API Key', pattern: /(?:api|key|token).*=.+/i },
  { name: 'Stripe Key', pattern: /sk_(?:live|test)_[0-9a-zA-Z]+/ },
  { name: 'Private Key', pattern: /-----BEGIN\s+(?:RSA\s+)?PRIVATE\s+KEY-----/ }
];

function auditDirectory(dir) {
  const findings = [];

  function walkDir(currentDir) {
    const files = fs.readdirSync(currentDir);

    for (const file of files) {
      const filePath = path.join(currentDir, file);
      const stat = fs.statSync(filePath);

      if (stat.isDirectory() && !['node_modules', '.git'].includes(file)) {
        walkDir(filePath);
      } else if (stat.isFile()) {
        const content = fs.readFileSync(filePath, 'utf8');

        for (const { name, pattern } of SECRET_PATTERNS) {
          const matches = content.match(pattern);
          if (matches) {
            findings.push({
              file: filePath,
              type: name,
              matches: matches.length
            });
          }
        }
      }
    }
  }

  walkDir(dir);
  return findings;
}

const findings = auditDirectory(process.cwd());

if (findings.length > 0) {
  console.error('🚨 SECURITY FINDINGS - Secrets detected in code:');
  findings.forEach(f => {
    console.error(`  - ${f.file}: ${f.type} (${f.matches} matches)`);
  });
  process.exit(1);
} else {
  console.log('✅ No secrets detected in codebase');
}
