// Secure secrets loading using AWS Secrets Manager
// This is the recommended approach for production applications

const AWS = require('aws-sdk');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Cache for secrets to reduce AWS API calls
let secretsCache = null;
let cacheExpiry = null;
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

/**
 * Load secrets from AWS Secrets Manager
 */
async function loadSecrets(secretName = 'production/myapp') {
  // Return cached secrets if still valid
  if (secretsCache && cacheExpiry && Date.now() < cacheExpiry) {
    return secretsCache;
  }

  try {
    const client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    const command = new GetSecretValueCommand({
      SecretId: secretName,
      VersionStage: 'AWSCURRENT'
    });

    const response = await client.send(command);

    let secret;
    if (response.SecretString) {
      // Parse JSON secret
      secret = JSON.parse(response.SecretString);
    } else {
      // Handle binary secrets
      secret = Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
    }

    // Cache the secrets
    secretsCache = secret;
    cacheExpiry = Date.now() + CACHE_TTL;

    return secret;
  } catch (error) {
    console.error('Error loading secrets from AWS Secrets Manager:', error.message);

    // During development, fall back to environment variables
    if (process.env.NODE_ENV !== 'production') {
      console.warn('Falling back to environment variables for development');
      return {
        databaseUrl: process.env.DATABASE_URL,
        awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
        awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
        anthropicApiKey: process.env.ANTHROPIC_API_KEY,
        stripeSecretKey: process.env.STRIPE_SECRET_KEY,
        jwtSecret: process.env.JWT_SECRET
      };
    }

    throw new Error('Failed to load required secrets');
  }
}

/**
 * Get a specific secret value with rotation support
 */
async function getSecretValue(key) {
  const secrets = await loadSecrets();
  return secrets[key];
}

/**
 * Validate that required secrets are present
 */
function validateSecrets(secrets, requiredKeys = []) {
  const missing = requiredKeys.filter(key => !secrets[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }
}

module.exports = {
  loadSecrets,
  getSecretValue,
  validateSecrets
};

