// Secure secrets loading using HashiCorp Vault
// Alternative to AWS Secrets Manager

const axios = require('axios');

// Cache for secrets
let secretsCache = null;
let vaultToken = null;
const VAULT_ADDR = process.env.VAULT_ADDR || 'http://localhost:8200';

/**
 * Authenticate with Vault
 */
async function authenticateWithVault() {
  const roleId = process.env.VAULT_ROLE_ID;
  const secretId = process.env.VAULT_SECRET_ID;

  if (!roleId || !secretId) {
    throw new Error('VAULT_ROLE_ID and VAULT_SECRET_ID must be set');
  }

  try {
    const response = await axios.post(
      `${VAULT_ADDR}/v1/auth/approle/login`,
      { role_id: roleId, secret_id: secretId }
    );

    vaultToken = response.data.auth.client_token;
    return vaultToken;
  } catch (error) {
    console.error('Vault authentication failed:', error.message);
    throw error;
  }
}

/**
 * Load secrets from Vault KV store
 */
async function loadSecrets(path = 'secret/data/myapp') {
  try {
    if (!vaultToken) {
      await authenticateWithVault();
    }

    const response = await axios.get(
      `${VAULT_ADDR}/v1/${path}`,
      {
        headers: {
          'X-Vault-Token': vaultToken,
          'X-Vault-Request': 'true'
        }
      }
