// Secure environment variable loading
// This pattern provides a secure way to load from .env during development
// while using a secrets manager in production

const fs = require('fs');
const path = require('path');

// Validation configuration
const SECRET_REQUIREMENTS = {
  JWT_SECRET: {
    required: true,
    minLength: 32,
    description: 'JWT signing secret'
  },
  DATABASE_URL: {
    required: true,
    pattern: /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/\w+$/,
    description: 'PostgreSQL connection string'
  },
  NODE_ENV: {
    required: true,
    allowed: ['development', 'test', 'production'],
    description: 'Application environment'
  },
  AWS_ACCESS_KEY_ID: {
    required: false, // Only required when using AWS services
    pattern: /^AKIA[0-9A-Z]{16}$/,
    description: 'AWS access key ID'
  },
  AWS_SECRET_ACCESS_KEY: {
    required: false,
    minLength: 40,
    description: 'AWS secret access key'
  },
  ANTHROPIC_API_KEY: {
    required: false,
    pattern: /^sk-ant-/,
    description: 'Anthropic API key'
  },
  STRIPE_SECRET_KEY: {
    required: false,
    pattern: /^sk_(live|test)_/,
    description: 'Stripe secret key'
  }
};

/**
 * Validate a single secret value against requirements
 */
function validateSecret(key, value) {
  const requirement = SECRET_REQUIREMENTS[key];

  if (!requirement) {
    console.warn(`Unknown secret key: ${key}`);
    return true;
  }

  if (requirement.required && (!value || value === '')) {
    throw new Error(`Required secret missing: ${key} (${requirement.description})`);
  }

  if (!value) {
    return true;
  }

  if (requirement.minLength && value.length < requirement.minLength) {
    throw new Error(
      `Secret "${key}" is too short (minimum ${requirement.minLength} characters)`
    );
  }

  if (requirement.pattern && !requirement.pattern.test(value)) {
    throw new Error(
      `Secret "${key}" has invalid format (${requirement.description})`
    );
  }

  // Detect canary/test values in production
  if (process.env.NODE_ENV === 'production') {
    const canaryPatterns = [
      /canary/i,
      /test/i,
      /example/i,
      /demo/i,
      /placeholder/i,
      /change/i
    ];

    for (const pattern of canaryPatterns) {
      if (pattern.test(value)) {
        throw new Error(
          `CRITICAL: Production deployment appears to use test credentials for "${key}"`
        );
      }
    }
  }

  return true;
}

/**
 * Load and validate all secrets
 */
function loadSecrets() {
  const secrets = {};

  // Check file permissions of .env files
  const envFiles = ['.env', `.env.${process.env.NODE_ENV}`];
  for (const envFile of envFiles) {
    const envPath = path.resolve(process.cwd(), envFile);

    if (fs.existsSync(envPath)) {
      const stats = fs.statSync(envPath);

      // Check permissions
      const mode = stats.mode;
      const worldReadable = (mode & 0o004) !== 0;
      const groupReadable = (mode & 0o040) !== 0;

      if (worldReadable || groupReadable) {
        console.warn(
          `⚠️  WARNING: ${envFile} has insecure permissions. Run: chmod 600 ${envFile}`
        );
      }

      // Check if tracked in git
      const gitDir = path.resolve(process.cwd(), '.git');
      if (fs.existsSync(gitDir)) {
        console.warn(
          `⚠️  WARNING: ${envFile} exists with .git directory. Ensure it's in .gitignore!`
        );
      }
    }
  }

  // Load all environment variables that match secret patterns
  for (const key of Object.keys(SECRET_REQUIREMENTS)) {
    const value = process.env[key];
    if (value !== undefined) {
      try {
        validateSecret(key, value);
        secrets[key] = value;
      } catch (error) {
        console.error(`Secret validation error for ${key}:`, error.message);
        throw error;
      }
    }
  }

  return secrets;
}

/**
 * Mask secrets for logging (prevent accidental logging of sensitive values)
 */
function maskSecrets(obj) {
  const masked = { ...obj };
  const secretKeys = [
    'SECRET', 'KEY', 'TOKEN', 'PASSWORD', 'DATABASE_URL',
    'AWS_SECRET_ACCESS_KEY', 'STRIPE_SECRET_KEY', 'API_KEY'
  ];

  for (const key in masked) {
    if (typeof masked[key] === 'string') {
      // Check if key indicates it's a secret
      const isSecret = secretKeys.some(pattern => key.includes(pattern));

      if (isSecret) {
        const value = masked[key];
        // Show first 4 and last 4 characters
        if (value.length > 8) {
          masked[key] = `${value.substring(0, 4)}...${value.substring(value.length - 4)}`;
        } else if (value.length > 0) {
