#!/usr/bin/env node

/**
 * Quick security audit script for secrets and configurations
 */

const fs = require('fs');
const path = require('path');

const COLORS = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  green: '\x1b[32m',
  blue: '\x1b[34m'
};

function log(level, message) {
  const color = {
    CRITICAL: COLORS.red,
    HIGH: COLORS.red,
    MEDIUM: COLORS.yellow,
    LOW: COLORS.green,
    INFO: COLORS.blue
  }[level] || COLORS.reset;

  console.log(`${color}[${level}]${COLORS.reset} ${message}`);
}

function auditFilePermissions() {
  log('INFO', '=== FILE PERMISSIONS AUDIT ===\n');

  const issues = [];
  const envFiles = ['.env', '.env.test', '.env.local', '.env.production'];

  for (const file of envFiles) {
    const filePath = path.resolve(process.cwd(), file);
    if (fs.existsSync(filePath)) {
      const stats = fs.statSync(filePath);
      const mode = stats.mode & 0o777; // Get permission bits

      const issuesFound = [];

      if ((mode & 0o004) !== 0) {
        issuesFound.push('world-readable');
      }
      if ((mode & 0o020) !== 0) {
        issuesFound.push('world-writable');
      }
      if ((mode & 0o040) !== 0) {
        issuesFound.push('group-readable');
      }
      if ((mode & 0o020) !== 0) {
        issuesFound.push('group-writable');
      }

      if (issuesFound.length > 0) {
        issues.push({
          file,
          severity: 'HIGH',
          message: `${file} is ${issuesFound.join(', ')} (mode: ${mode.toString(8)})`
        });
        log('HIGH', `❌ ${file} - Mode: ${mode.toString(8)} (${issuesFound.join(', ')})`);
      } else {
        log('INFO', `✓ ${file} - Mode: ${mode.toString(8)} (secure)`);
      }
    }
  }

  return issues;
}

function auditGitignore() {
  log('\nINFO', '=== GITIGNORE AUDIT ===\n');

  const gitignorePath = path.resolve(process.cwd(), '.gitignore');
  const secretsIssues = [];

  if (!fs.existsSync(gitignorePath)) {
    secretsIssues.push({
      severity: 'HIGH',
      message: '.gitignore file not found'
    });
    log('HIGH', '❌ .gitignore file not found');
    return secretsIssues;
  }

  const gitignore = fs.readFileSync(gitignorePath, 'utf-8');
  const shouldIgnore = ['.env', '.env.local', '.env.*.local'];

  for (const pattern of shouldIgnore) {
    const isIgnored = gitignore.split('\n').some(line => {
      const trimmed = line.trim();
      return trimmed && !trimmed.startsWith('#') && trimmed === pattern;
    });

    if (!isIgnored) {
      secretsIssues.push({
        severity: 'MEDIUM',
        message: `${pattern} not in .gitignore`
      });
      log('MEDIUM', `⚠️  ${pattern} not found in .gitignore`);
    } else {
      log('INFO', `✓ ${pattern} is in .gitignore`);
    }
  }

  // Check if .env files are tracked by git
  const gitDir = path.resolve(process.cwd(), '.git');
  if (fs.existsSync(gitDir)) {
    const filesToCheck = ['.env.test', '.env', '.env.local'];
    for (const file of filesToCheck) {
      const filePath = path.resolve(process.cwd(), file);
      if (fs.existsSync(filePath)) {
        log('HIGH', `❌ ${file} exists and may be tracked by git!`);
        secretsIssues.push({
          severity: 'CRITICAL',
          message: `${file} exists in workspace with .git directory`
        });
      }
    }
  }

  return secretsIssues;
}

function auditEnvTest() {
  log('\nINFO', '=== .env.test CONTENT AUDIT ===\n');

  const envTestPath = path.resolve(process.cwd(), '.env.test');
  const issues = [];

  if (!fs.existsSync(envTestPath)) {
    log('INFO', '.env.test not found - OK');
    return issues;
  }

  const content = fs.readFileSync(envTestPath, 'utf-8');

  // Count potential secrets
  const lines = content.split('\n').filter(line => line && !line.startsWith('#'));
  log('INFO', `Found ${lines.length} secret(s) in .env.test`);

  // Check for suspected real vs test values
  for (const line of lines) {
    const [key, value] = line.split('=');
    if (value) {
      const isTestValue = /canary|test|dummy|example|change/i.test(value);

      if (!isTestValue) {
        issues.push({
          severity: 'MEDIUM',
          key: key,
          message: `Value for ${key} appears to be a real credential`
        });
        log('MEDIUM', `⚠️  ${key} may contain a real credential`);
      } else {
        log('INFO', `✓ ${key} appears to be a test/canary value`);
      }
    }
  }

  // Check for weak patterns
  if (/password\s*=\s*["']?(password|123|admin)["']?/i.test(content)) {
    issues.push({
      severity: 'LOW',
      message: 'Weak password pattern detected'
    });
    log('LOW', '⚠️  Weak password pattern found');
  }

  return issues;
}

function auditAppJs() {
  log('\nINFO', '=== app.js CONFIGURATION AUDIT ===\n');

  const appJsPath = path.resolve(process.cwd(), 'app.js');
  const issues = [];

  if (!fs.existsSync(appJsPath)) {
    log('INFO', 'app.js not found');
    return issues;
  }

  const content = fs.readFileSync(appJsPath, 'utf-8');

  // Check for dotenv
  if (content.includes("require('dotenv')") || content.includes("require(\"dotenv\")")) {
    log('INFO', '✓ app.js uses dotenv for environment loading');
  } else if (content.includes('process.env')) {
    issues.push({
      severity: 'MEDIUM',
      message: 'app.js uses process.env but does not load dotenv'
    });
    log('MEDIUM', '⚠️  app.js uses process.env but dotenv is not configured');
  } else {
    log('INFO', 'ℹ️  app.js does not use environment variables');
  }

  // Check for secrets manager integration
  const secretsManagers = ['@aws-sdk/client-secrets-manager', 'vault', 'aws-sdk'];
  const hasSecretsManager = secretsManagers.some(pkg => content.includes(pkg));

  if (hasSecretsManager) {
    log('INFO', '✓ app.js integrates with a secrets manager');
  } else {
    issues.push({
      severity: 'LOW',
      message: 'No secrets manager integration detected'
    });
    log('LOW', 'ℹ️  No secrets manager integration found (consider adding)');
  }

  // Check for hardcoded secrets
  const secretPatterns = [
    { pattern: /password\s*[=:]\s*['"][^'"]+['"]/i, name: 'password' },
    { pattern: /secret\s*[=:]\s*['"][^'"]+['"]/i, name: 'secret' },
    { pattern: /api[_-]?key\s*[=:]\s*['"][^'"]+['"]/i, name: 'API key' }
  ];

  for (const { pattern, name } of secretPatterns) {
    if (pattern.test(content)) {
      issues.push({
        severity: 'HIGH',
        message: `Hardcoded ${name} detected in app.js`
      });
      log('HIGH', `❌ Hardcoded ${name} found in app.js`);
    }
  }

  return issues;
}

function main() {
  console.log(`${COLORS.blue}═══════════════════════════════════════════════════${COLORS.reset}`);
  console.log(`${COLORS.blue}     SECRETS & CONFIGURATION SECURITY AUDIT${COLORS.reset}`);
  console.log(`${COLORS.blue}═══════════════════════════════════════════════════${COLORS.reset}\n`);

  const allIssues = [
    ...auditFilePermissions(),
    ...auditGitignore(),
    ...auditEnvTest(),
    ...auditAppJs()
  ];

  // Summary
  log('\nINFO', '\n=== AUDIT SUMMARY ===\n');

  const criticalCount = allIssues.filter(i => i.severity === 'CRITICAL').length;
  const highCount = allIssues.filter(i => i.severity === 'HIGH').length;
  const mediumCount = allIssues.filter(i => i.severity === 'MEDIUM').length;
  const lowCount = allIssues.filter(i => i.severity === 'LOW').length;

  log('CRITICAL', `Critical issues: ${criticalCount}`);
  log('HIGH', `High issues: ${highCount}`);
  log('MEDIUM', `Medium issues: ${mediumCount}`);
  log('LOW', `Low issues: ${lowCount}\n`);

  if (allIssues.length > 0) {
    console.log('=== ISSUES DETECTED ===\n');
    console.table(allIssues);
  }

  // Recommendations
  if (criticalCount > 0 || highCount > 0) {
    log('HIGH', '\n=== IMMEDIATE ACTIONS REQUIRED ===\n');
    console.log('1. Run: chmod 600 .env* (fix file permissions)');
    console.log('2. Add .env files to .gitignore');
    console.log('3. Remove any secrets from version control');
  }

  if (!allIssues.some(i => i.severity === 'CRITICAL' || i.severity === 'HIGH')) {
    log('INFO', '\n✓ No critical or high severity issues detected!');
  }

  process.exit(allIssues.some(i => i.severity === 'CRITICAL') ? 1 : 0);
}

if (require.main === module) {
  main();
}

module.exports = {
  auditFilePermissions,
  auditGitignore,
  auditEnvTest,
  auditAppJs
};

