// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheExpiry = new Map();
    this.CACHE_TTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    const now = Date.now();

    // Return cached value if valid and not forced to refresh
    if (!forceRefresh && this.cache.has(secretName)) {
      if (now < this.cacheExpiry.get(secretName)) {
        return this.cache.get(secretName);
      }
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName
      });

      const response = await this.client.send(command);

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = JSON.parse(Buffer.from(response.SecretBinary, 'base64').toString('utf-8'));
      }

      // Cache the secret
      this.cache.set(secretName, secret);
      this.cacheExpiry.set(secretName, now + this.CACHE_TTL);

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async clearCache(secretName) {
    if (secretName) {
      this.cache.delete(secretName);
      this.cacheExpiry.delete(secretName);
    } else {
      this.cache.clear();
      this.cacheExpiry.clear();
    }
  }
}

module.exports = new SecretsManager();
