// config/secrets-provider.js
class SecretsProvider {
  constructor() {
    this.provider = process.env.SECRETS_PROVIDER || 'env';
  }

  async getSecret(key) {
    switch (this.provider) {
      case 'aws':
        return this.getFromAWS(key);
      case 'vault':
        return this.getFromVault(key);
      case 'gcp':
        return this.getFromGCP(key);
      case 'env':
      default:
        return this.getFromEnv(key);
    }
  }

  getFromEnv(key) {
