// config/validate-secrets.js
const requiredSecrets = {
  DATABASE_URL: {
    pattern: /^postgres:\/\/.+$/,
    description: 'PostgreSQL connection string'
  },
  JWT_SECRET: {
    minLength: 32,
    description: 'JWT signing secret (min 32 characters)'
  },
  STRIPE_SECRET_KEY: {
    pattern: /^sk_(live|test)_/,
    description: 'Stripe API secret key'
  }
};

function validateSecrets() {
  const errors = [];

  for (const [key, validation] of Object.entries(requiredSecrets)) {
    const value = process.env[key];

    if (!value) {
      errors.push(`Missing required secret: ${key}`);
      continue;
    }

    if (validation.pattern && !validation.pattern.test(value)) {
      errors.push(`Invalid format for ${key}: ${validation.description}`);
    }

    if (validation.minLength && value.length < validation.minLength) {
      errors.push(`${key} must be at least ${validation.minLength} characters`);
    }

