// secrets.js - AWS Secrets Manager integration
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretsClient = new SecretsManagerClient({ 
  region: process.env.AWS_REGION || 'us-east-1' 
});

let cachedSecrets = null;
let cacheExpiry = null;
const CACHE_TTL = 300000; // 5 minutes

async function loadSecrets(forceRefresh = false) {
  // Return cached secrets if still valid
  if (cachedSecrets && cacheExpiry && Date.now() < cacheExpiry && !forceRefresh) {
    return cachedSecrets;
  }

  try {
    // Fetch secret from AWS Secrets Manager
    const command = new GetSecretValueCommand({
      SecretId: process.env.SECRETS_ARN || 'myapp/production'
    });

    const response = await secretsClient.send(command);

    if (response.SecretString) {
      cachedSecrets = JSON.parse(response.SecretString);
      cacheExpiry = Date.now() + CACHE_TTL;

      return cachedSecrets;
    }

    throw new Error('No secret string returned from AWS Secrets Manager');
  } catch (error) {
    console.error('Failed to load secrets:', error.message);
    throw error;
  }
