// secrets-manager.js - Provider-agnostic secrets loader
class SecretsManager {
  constructor(provider = 'env') {
    this.provider = provider;
    this.cache = new Map();
    this.ttl = 300000; // 5 min cache
  }

  async get(key) {
    const cached = this.cache.get(key);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    let value;

    switch (this.provider) {
      case 'aws-secrets-manager':
        value = await this.getFromAWS(key);
        break;
      case 'vault':
        value = await this.getFromVault(key);
        break;
      case 'env':
      default:
        value = process.env[key];
        if (!value) throw new Error(`Secret ${key} not found`);
    }

    this.cache.set(key, { value, expiresAt: Date.now() + this.ttl });
    return value;
  }

  async getFromAWS(key) {
    // AWS Secrets Manager implementation
    const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
    const client = new SecretsManagerClient();
    const response = await client.send(new GetSecretValueCommand({ SecretId: key }));
    return JSON.parse(response.SecretString);
  }

  async getFromVault(key) {
    // HashiCorp Vault implementation
    const vault = require('node-vault')();
    const result = await vault.read(`secret/data/${key}`);
    return result.data.data;
  }
}

module.exports = SecretsManager;
