  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();

      if ('SecretString' in data) {
        const secret = JSON.parse(data.SecretString);
        this.cache.set(secretName, { value: secret, timestamp: Date.now() });
        return secret;
      }

      throw new Error('Secret binary not supported');
    } catch (error) {
      console.error(`Error fetching secret ${secretName}:`, error.message);
      throw error;
    }
  }

  async loadAllSecrets(secretNames) {
    const secrets = {};
    for (const name of secretNames) {
      secrets[name] = await this.getSecret(name);
    }
    return secrets;
  }
}

